from seven_desks.settings import CACHE as BUILD_ROOT, LAKE, SOURCE as REVIEW_SOURCE, FROZEN_VERSION
from seven_desks.store import version_root, connect
"""Rebuild owner aggregates from conservative share-class adjustments, offline."""
from pathlib import Path
import duckdb,json
P=Path(__file__).resolve().parents[2]
OUT=(BUILD_ROOT / 'ac-fix')
LOCAL=(BUILD_ROOT / 'owners')
SRC=(REVIEW_SOURCE / 'owners')
c=connect(config={'threads':2,'memory_limit':'5GB'})
c.execute('SET preserve_insertion_order=false')
for folder,prefix in [(SRC,'s_'),(LOCAL,'l_')]:
 for p in folder.glob('*.parquet'):
  if not p.name.startswith(('_','tmp_')): c.execute(f"CREATE VIEW {prefix+p.stem} AS SELECT * FROM read_parquet('{p}')")
c.execute(f"CREATE VIEW corrected AS SELECT * FROM '{OUT}/fund_holdings_corrected.parquet'")
c.execute(f"CREATE VIEW adjustments AS SELECT * FROM '{OUT}/amount_adjustments.parquet'")
def emit(name,sql):
 c.execute(f"COPY ({sql}) TO '{OUT/name}.parquet' (FORMAT PARQUET,COMPRESSION ZSTD)")
 c.execute(f"CREATE OR REPLACE VIEW x_{name} AS SELECT * FROM '{OUT/name}.parquet'")
 print(name,flush=True)
def mid(v):
 return f"CASE WHEN {v} IS NOT NULL THEN (rank() OVER(PARTITION BY report_period,({v} IS NOT NULL) ORDER BY {v})-1+0.5*count(*) OVER(PARTITION BY report_period,{v}))/count(*) OVER(PARTITION BY report_period,({v} IS NOT NULL)) END"
# The same company mapping used by the original calculation. Count columns are untouched.
c.execute("""CREATE TEMP TABLE delta AS SELECT p.company_id,a.report_period,a.holding_symbol symbol,sum(a.original_market_value) mv,sum(a.original_shares) shares FROM adjustments a JOIN s_active_fund_universe p ON p.symbol=a.fund_symbol GROUP BY ALL""")
emit('company_stock_holdings',"""WITH x AS(SELECT o.* REPLACE(o.market_value-coalesce(d.mv,0) AS market_value,o.shares-coalesce(d.shares,0) AS shares) FROM s_company_stock_holdings o LEFT JOIN delta d USING(company_id,report_period,symbol)),y AS(SELECT * REPLACE(shares/nullif(float_shares,0) AS float_holding_ratio,market_value/nullif(sum(market_value) OVER(PARTITION BY company_id,report_period),0) AS weight,rank() OVER(PARTITION BY company_id,report_period ORDER BY market_value DESC NULLS LAST) AS holding_rank) FROM x) SELECT * REPLACE(quality_status||';verified_ac_dedup_in_known_periods' AS quality_status) FROM y""")
# Deduplicate independently within each comparable-fund cohort, so a missing
# representative does not erase a visible member from a comparison leg.
c.execute("""CREATE TEMP TABLE cohort_legs AS SELECT f.company_id,f.report_period,f.prev_period,h.report_period=h.report_period AND h.report_period=f.report_period current_leg,h.holding_symbol symbol,h.shares,h.market_value,row_number() OVER(PARTITION BY f.company_id,f.report_period,h.report_period,h.ac_representative,h.holding_symbol ORDER BY h.fund_symbol) rn FROM s_company_comparable_funds f JOIN corrected h ON h.fund_symbol=f.fund_symbol AND h.report_period IN (f.report_period,f.prev_period)""")
emit('company_changes',"""WITH a AS(SELECT company_id entity_id,report_period,prev_period,symbol,count(*) FILTER(WHERE current_leg)>0 current_present,count(*) FILTER(WHERE NOT current_leg)>0 previous_present,sum(shares) FILTER(WHERE current_leg AND rn=1) current_shares,sum(shares) FILTER(WHERE NOT current_leg AND rn=1) previous_shares,sum(market_value) FILTER(WHERE current_leg AND rn=1) current_value,sum(market_value) FILTER(WHERE NOT current_leg AND rn=1) previous_value FROM cohort_legs GROUP BY ALL), b AS(SELECT o.* REPLACE(a.current_present AS current_present,a.previous_present AS previous_present,a.current_shares AS current_shares,a.previous_shares AS previous_shares,a.current_value AS current_value,a.previous_value AS previous_value,CASE WHEN o.unknown_split_events=0 THEN a.previous_shares*o.split_multiplier END AS previous_adjusted_shares,CASE WHEN o.unknown_split_events=0 THEN a.current_shares/nullif(a.previous_shares*o.split_multiplier,0)-1 END AS share_change_ratio) FROM s_company_changes o JOIN a ON o.entity_id=a.entity_id AND o.report_period=a.report_period AND o.symbol=a.symbol), z AS(SELECT * REPLACE(CASE WHEN comparable_coverage_ratio<.8 THEN 'unknown_company_cohort_coverage_below_80pct' WHEN unknown_split_events>0 THEN 'unknown_split_event' WHEN NOT previous_present AND current_present THEN 'new_visible' WHEN NOT current_present AND previous_present THEN 'exit_visible' WHEN share_change_ratio>.020000000001 THEN 'increase' WHEN share_change_ratio<-.020000000001 THEN 'decrease' WHEN share_change_ratio IS NOT NULL THEN 'unchanged' ELSE 'unknown_shares' END AS change_status) FROM b) SELECT * REPLACE(CASE WHEN starts_with(change_status,'unknown') THEN NULL WHEN NOT previous_present THEN current_shares*close ELSE (coalesce(current_shares,0)-previous_adjusted_shares)*close END AS estimated_change_value,comparison_status||';ac_dedup_within_cohort' AS comparison_status) FROM z""")
emit('company_period',"""WITH a AS(SELECT company_id,report_period,sum(market_value) visible_market_value,count(*) stock_count,sum(power(weight,2)) hhi,sum(weight) FILTER(WHERE holding_rank<=10) top10_weight,max(latest_announce) latest_announce,avg(value_count*1.0/row_count) coverage_ratio FROM x_company_stock_holdings WHERE month(report_period) IN(6,12) GROUP BY ALL),ch AS(SELECT entity_id company_id,report_period,CASE WHEN count(*) FILTER(WHERE NOT starts_with(change_status,'unknown'))>0 THEN count(*) FILTER(WHERE change_status='new_visible') END new_count,CASE WHEN count(*) FILTER(WHERE NOT starts_with(change_status,'unknown'))>0 THEN count(*) FILTER(WHERE change_status='increase') END increase_count,CASE WHEN count(*) FILTER(WHERE NOT starts_with(change_status,'unknown'))>0 THEN count(*) FILTER(WHERE change_status='decrease') END decrease_count,CASE WHEN count(*) FILTER(WHERE NOT starts_with(change_status,'unknown'))>0 THEN count(*) FILTER(WHERE change_status='exit_visible') END exit_count,sum(estimated_change_value) estimated_net_change,sum(abs(estimated_change_value)) gross_estimated_change,CASE WHEN count(*) FILTER(WHERE NOT starts_with(change_status,'unknown'))>0 THEN count(*) FILTER(WHERE change_status IN('new_visible','exit_visible')) END changed_stock_count FROM x_company_changes GROUP BY ALL) SELECT o.* REPLACE(a.visible_market_value AS visible_market_value,a.stock_count AS stock_count,a.hhi AS hhi,a.top10_weight AS top10_weight,a.latest_announce AS latest_announce,a.coverage_ratio AS coverage_ratio,ch.new_count AS new_count,ch.increase_count AS increase_count,ch.decrease_count AS decrease_count,ch.exit_count AS exit_count,ch.estimated_net_change AS estimated_net_change,ch.gross_estimated_change AS gross_estimated_change,ch.changed_stock_count AS changed_stock_count,CASE WHEN a.visible_market_value>2e11 THEN 'top' WHEN a.visible_market_value>=5e10 THEN 'large' WHEN a.visible_market_value>=1e10 THEN 'medium' ELSE 'small' END AS size_band,ch.gross_estimated_change/nullif(2*a.visible_market_value,0) AS estimated_amount_turnover,ch.changed_stock_count*1.0/nullif(a.stock_count,0) AS stock_turnover,o.quality_status||';verified_ac_dedup_in_known_periods' AS quality_status) FROM s_company_period o JOIN a USING(company_id,report_period) LEFT JOIN ch USING(company_id,report_period)""")
emit('company_industry',"""SELECT company_id,report_period,coalesce(industry_code,'unknown') industry_code,any_value(industry_name) industry_name,sum(market_value) market_value,sum(weight) weight,count(*) stock_count,'historical_members_current_SW2021_taxonomy;verified_ac_dedup_in_known_periods' quality_status FROM x_company_stock_holdings WHERE month(report_period) IN(6,12) GROUP BY ALL""")
emit('company_overlap',"""WITH shared AS(SELECT a.report_period,a.company_id company_a,b.company_id company_b,count(*) intersection_count,sum(least(a.weight,b.weight)) weight_overlap FROM x_company_stock_holdings a JOIN x_company_stock_holdings b ON a.report_period=b.report_period AND a.symbol=b.symbol AND a.company_id<b.company_id WHERE month(a.report_period) IN(6,12) GROUP BY ALL),pairs AS(SELECT a.report_period,a.company_id company_a,b.company_id company_b,a.stock_count+b.stock_count total_count FROM x_company_period a JOIN x_company_period b ON a.report_period=b.report_period AND a.company_id<b.company_id) SELECT p.report_period,p.company_a,p.company_b,coalesce(s.intersection_count,0) intersection_count,p.total_count-coalesce(s.intersection_count,0) union_count,coalesce(s.intersection_count,0)*1.0/nullif(p.total_count-coalesce(s.intersection_count,0),0) jaccard,coalesce(s.weight_overlap,0) weight_overlap,'sum_min_normalized_visible_market_value_weights' formula FROM pairs p LEFT JOIN shared s USING(report_period,company_a,company_b)""")
c.execute("""CREATE TEMP TABLE crowd_base AS WITH h AS(SELECT report_period,symbol,sum(market_value) market_value,sum(shares) shares,count(*) company_count,sum(fund_count)::DOUBLE share_class_count,any_value(float_shares) float_shares,any_value(industry_code) industry_code,sum(shares)/nullif(any_value(float_shares),0) float_ratio FROM x_company_stock_holdings WHERE month(report_period) IN(6,12) GROUP BY ALL),ch AS(SELECT report_period,symbol,CASE WHEN count(*) FILTER(WHERE NOT starts_with(change_status,'unknown'))>0 THEN count(*) FILTER(WHERE change_status IN('new_visible','increase')) END buyers,CASE WHEN count(*) FILTER(WHERE NOT starts_with(change_status,'unknown'))>0 THEN count(*) FILTER(WHERE change_status IN('exit_visible','decrease')) END sellers,count(*) FILTER(WHERE NOT starts_with(change_status,'unknown')) comparable_company_count FROM x_company_changes GROUP BY ALL) SELECT h.*,ch.buyers,ch.sellers,ch.comparable_company_count,o.list_date,o.ipo_status FROM h JOIN s_fund_stock_crowding o USING(report_period,symbol) LEFT JOIN ch USING(report_period,symbol)""")
emit('fund_stock_crowding',f"""WITH ranks AS(SELECT report_period,symbol,{mid('company_count')} company_percentile,{mid('float_ratio')} float_percentile FROM crowd_base WHERE ipo_status='eligible_preperiod_listed') SELECT b.*,r.company_percentile,r.float_percentile,50*(r.company_percentile+r.float_percentile) crowding_score,CASE WHEN b.ipo_status<>'eligible_preperiod_listed' OR buyers IS NULL OR sellers IS NULL THEN NULL WHEN buyers>=3 AND buyers>=3*sellers THEN 'buy' WHEN sellers>=3 AND sellers>=3*buyers THEN 'sell' ELSE 'none' END consensus,'cross_section_midrank_nonmissing;period_IPO_excluded;period_known_float;comparable_fund_cohort_changes;verified_ac_dedup_in_known_periods' quality_status FROM crowd_base b LEFT JOIN ranks r USING(report_period,symbol)""")
